import 'dart:convert';

import 'package:flutter/foundation.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:shared_preferences/shared_preferences.dart';

import '../services/elio_feedback.dart';
import '../services/quiz_tts_service.dart';

/// Where quiz questions come from (decision 0018): the reviewed bank, or
/// generated by the cloud AI for the scanned object, with the bank as its
/// offline fallback (decision 0179).
enum QuestionSource { bank, ai }

const defaultQuestionSource = QuestionSource.ai;

/// `--dart-define=TESTER_BUILD=true`: a release-mode build for sideloaded phone
/// testing. It shows the source switch and the tester log panel (decision 0040).
const testerBuild = bool.fromEnvironment('TESTER_BUILD');

/// UI-only application preferences (not device connection related),
/// persisted so quiz settings (difficulty, skip) survive restarts.
class AppPreferences {
  final bool soundEffects;
  final double masterVolume;
  final String quizDifficulty;
  final String quizTimer;
  final bool skipAllowed;

  /// The Config screen's "Quiz questions" choice, saved since decision 0145.
  /// A saved ELIOS AI choice is safe: with no AI answer a quiz falls back to
  /// the bank, and says so.
  final QuestionSource questionSource;

  /// ELIOS setup quiz card (ELIOS 3, decision 0198): robot scans have their
  /// own on/off and question source; [questionSource] is for phone scans.
  final bool robotQuizEnabled;
  final QuestionSource robotQuestionSource;

  const AppPreferences({
    this.soundEffects = true,
    this.masterVolume = 0.75,
    this.quizDifficulty = 'Medium',
    this.quizTimer = '60s',
    this.skipAllowed = false,
    this.questionSource = defaultQuestionSource,
    this.robotQuizEnabled = true,
    this.robotQuestionSource = defaultQuestionSource,
  });

  AppPreferences copyWith({
    bool? soundEffects,
    double? masterVolume,
    String? quizDifficulty,
    String? quizTimer,
    bool? skipAllowed,
    QuestionSource? questionSource,
    bool? robotQuizEnabled,
    QuestionSource? robotQuestionSource,
  }) {
    return AppPreferences(
      soundEffects: soundEffects ?? this.soundEffects,
      masterVolume: masterVolume ?? this.masterVolume,
      quizDifficulty: quizDifficulty ?? this.quizDifficulty,
      quizTimer: quizTimer ?? this.quizTimer,
      skipAllowed: skipAllowed ?? this.skipAllowed,
      questionSource: questionSource ?? this.questionSource,
      robotQuizEnabled: robotQuizEnabled ?? this.robotQuizEnabled,
      robotQuestionSource: robotQuestionSource ?? this.robotQuestionSource,
    );
  }

  Map<String, dynamic> toMap() => {
    'soundEffects': soundEffects,
    'masterVolume': masterVolume,
    'quizDifficulty': quizDifficulty,
    'quizTimer': quizTimer,
    'skipAllowed': skipAllowed,
    'questionSource': questionSource.name,
    'robotQuizEnabled': robotQuizEnabled,
    'robotQuestionSource': robotQuestionSource.name,
  };

  factory AppPreferences.fromMap(Map<String, dynamic> map) {
    const d = AppPreferences();
    return AppPreferences(
      soundEffects: map['soundEffects'] is bool
          ? map['soundEffects'] as bool
          : d.soundEffects,
      masterVolume: map['masterVolume'] is num
          ? (map['masterVolume'] as num).toDouble()
          : d.masterVolume,
      // Older builds saved the Indonesian label; the quiz only reads the English value.
      quizDifficulty: switch (map['quizDifficulty']) {
        'Mudah' => 'Easy',
        'Sedang' => 'Medium',
        'Sulit' => 'Hard',
        final String v => v,
        _ => d.quizDifficulty,
      },
      quizTimer: map['quizTimer'] is String
          ? map['quizTimer'] as String
          : d.quizTimer,
      skipAllowed: map['skipAllowed'] is bool
          ? map['skipAllowed'] as bool
          : d.skipAllowed,
      questionSource:
          QuestionSource.values.asNameMap()[map['questionSource']] ??
          d.questionSource,
      robotQuizEnabled: map['robotQuizEnabled'] is bool
          ? map['robotQuizEnabled'] as bool
          : d.robotQuizEnabled,
      // Before 0198 one source served both; robots keep the saved choice.
      robotQuestionSource:
          QuestionSource.values.asNameMap()[map['robotQuestionSource'] ??
              map['questionSource']] ??
          d.robotQuestionSource,
    );
  }
}

final appPreferencesProvider =
    NotifierProvider<AppPreferencesNotifier, AppPreferences>(
      AppPreferencesNotifier.new,
    );

/// Profile → Sound effects (legacy mirror; sounds go through [ElioSound]).
bool soundEffectsOn = true;

/// Pushes Sound effects and Master volume to the one audio service and the
/// quiz voice, so a change applies at once everywhere (decision 0201).
void applySoundPrefs(AppPreferences p) {
  soundEffectsOn = p.soundEffects;
  ElioSound.instance
    ..enabled = p.soundEffects
    ..volume = p.masterVolume;
  QuizTtsService.instance.volume = p.masterVolume;
}

class AppPreferencesNotifier extends Notifier<AppPreferences> {
  static const _key = 'app_preferences_v1';
  bool _touched = false;

  @override
  AppPreferences build() {
    listenSelf((_, next) => applySoundPrefs(next));
    _load();
    const initial = AppPreferences();
    applySoundPrefs(initial);
    return initial;
  }

  Future<void> _load() async {
    try {
      final raw = (await SharedPreferences.getInstance()).getString(_key);
      // Don't overwrite a change the user made while this was loading.
      if (raw != null && !_touched) {
        state = AppPreferences.fromMap(jsonDecode(raw) as Map<String, dynamic>);
      }
    } catch (e) {
      debugPrint('AppPreferences load failed: $e');
    }
  }

  void update(AppPreferences Function(AppPreferences) patch) {
    _touched = true;
    state = patch(state);
    final snapshot = state;
    SharedPreferences.getInstance()
        .then((p) => p.setString(_key, jsonEncode(snapshot.toMap())))
        .catchError((Object e) {
          debugPrint('AppPreferences save failed: $e');
          return false;
        });
  }
}
